-- Room boundaries and schedule links for the locations in 002_schedule.sql.
CREATE TABLE rooms (
    id integer GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    venue text NOT NULL,
    floor integer NOT NULL,
    name text NOT NULL,
    boundary jsonb NOT NULL CHECK ((boundary->>'type' = 'Polygon') IS TRUE),
    UNIQUE (venue, floor, name)
);

CREATE TABLE location_rooms (
    location_id integer REFERENCES locations(id) ON DELETE CASCADE,
    room_id integer REFERENCES rooms(id) ON DELETE CASCADE,
    PRIMARY KEY (location_id, room_id)
);

-- Boundaries from app/map.html in GeoJSON longitude, latitude order.

-- Resolve stable venue, level and label keys against the schedule seed.
SELECT locations.id, rooms.id
FROM (VALUES
    ('Salt Palace', 1, 'Grand Ballroom ACE', ARRAY['Ballroom A', 'Ballroom C', 'Ballroom E']),
    ('Salt Palace', 1, 'Grand Ballroom BDF', ARRAY['Ballroom B', 'Ballroom D', 'Ballroom F']),
    ('Salt Palace', 1, 'Grand Ballroom H', ARRAY['Ballroom H']),
    ('Salt Palace', 1, '151', ARRAY['Room 151']),
    ('Salt Palace', 2, '255 BC', ARRAY['255B', '255C']),
    ('Salt Palace', 2, '255 EF', ARRAY['255E', '255F']),
    ('Salt Palace', 1, 'Grand Ballroom J', ARRAY['Ballroom J']),
    ('Salt Palace', 2, '255 A', ARRAY['255A']),
    ('Hyatt Regency', 5, 'Capitol Reef', ARRAY['Capitol Reef']),
    ('Hyatt Regency', 4, 'Regency Ballroom B-D', ARRAY['Regency B', 'Regency C', 'Regency D']),
    ('Salt Palace', 1, 'Hall DE', ARRAY['Hall D', 'Hall E']),
    ('Salt Palace', 1, 'Halls A-C, Halls 1-5', ARRAY['Hall A', 'Hall B', 'Hall C', 'Hall 1', 'Hall 2', 'Hall 3', 'Hall 4', 'Hall 5']),
    ('Salt Palace', 1, 'Hall 5 | Cosmic Canyon Zone | Project Pavilion', ARRAY['Hall 5']),
    ('Salt Palace', 1, 'Hall 1 | Alpine Overlook Zone | Demo Theater', ARRAY['Hall 1']),
    ('Salt Palace', 1, 'Halls 5 | Cosmic Canyon Zone', ARRAY['Hall 5']),
    ('Salt Palace', 1, 'Hall 1 | Alpine Overlook Zone | Network Nook', ARRAY['Hall 1']),
    ('Salt Palace', 1, 'Hall B | Starlight Summit Zone', ARRAY['Hall B']),
    ('Salt Palace', 1, 'Grand Ballroom GI', ARRAY['Ballroom G', 'Ballroom I']),
    ('Hyatt Regency', 2, 'Salt Lake Ballroom C', ARRAY['Salt Lake C']),
    ('Hyatt Regency', 2, 'Salt Lake Ballroom DE', ARRAY['Salt Lake D', 'Salt Lake E']),
    ('Hyatt Regency', 4, 'Regency Ballroom CD', ARRAY['Regency C', 'Regency D']),
    ('Hyatt Regency', 4, 'Regency Ballroom A', ARRAY['Regency A']),
    ('Salt Palace', 2, '255 D', ARRAY['255D'])
) AS mapping (venue, floor, label, room_names)
JOIN locations ON locations.venue = mapping.venue
    AND locations.level = 'Level ' || mapping.floor
    AND locations.room = mapping.label
JOIN rooms ON rooms.venue = mapping.venue
    AND rooms.floor = mapping.floor
    AND rooms.name = ANY(mapping.room_names);
